package com.mo.economy_system.common.territory;
import static org.junit.jupiter.api.Assertions.*;import java.lang.ref.WeakReference;import java.util.*;import org.junit.jupiter.api.Test;
class TerritoryInviteStoreTest{private static TerritoryInvite invite(UUID id,UUID territory,UUID target,long a,long b){UUID owner=UUID.randomUUID();return new TerritoryInvite(id,territory,owner,owner,target,"land","owner","target",a,b);}@Test void deduplicatesExpiresAndResets(){TerritoryInviteStore s=new TerritoryInviteStore(2);UUID target=UUID.randomUUID(),territory=UUID.randomUUID();TerritoryInvite a=invite(UUID.randomUUID(),territory,target,0,1200);assertEquals(TerritoryInviteStore.PutResult.CREATED,s.put(a,0));assertEquals(TerritoryInviteStore.PutResult.ALREADY_PENDING,s.put(invite(UUID.randomUUID(),territory,target,1,1201),1));assertTrue(s.find(a.inviteId(),1199).isPresent());assertTrue(s.find(a.inviteId(),1200).isEmpty());TerritoryInvite b=invite(UUID.randomUUID(),territory,target,1000,2200);s.put(b,1000);assertEquals(0,s.size(0));}@Test void claimConsumesOnce(){TerritoryInviteStore s=new TerritoryInviteStore();UUID target=UUID.randomUUID();TerritoryInvite i=invite(UUID.randomUUID(),UUID.randomUUID(),target,0,10);s.put(i,0);assertEquals(TerritoryInviteStore.ClaimResult.CLAIMED,s.claim(i.inviteId(),target,0));assertEquals(TerritoryInviteStore.ClaimResult.BUSY,s.claim(i.inviteId(),target,0));assertTrue(s.consume(i.inviteId()));assertFalse(s.consume(i.inviteId()));}}
